const raw = $input.first().json;
const item = raw.body || raw;
const email = (item.email || '').trim().toLowerCase();
const phone = (item.phone || '').replace(/\D/g, '');
const name = (item.name || '').trim();
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const phoneValid = phone.length >= 7;
const leadId = item.leadId || ('wf_' + Date.now() + '_' + Math.floor(Math.random()*10000));

return [{
  leadId,
  name,
  email,
  phone,
  company: (item.company || '').trim(),
  position: (item.position || '').trim(),
  message: (item.message || '').trim(),
  source: item.source || 'web',
  isValid: emailValid || phoneValid,
  receivedAt: new Date().toISOString()
}];

const d = $input.first().json;

const systemPrompt = 'You are a B2B Lead Scoring AI. Analyze the lead data and return ONLY a JSON object with fields: leadScore (0-100), leadTier ("hot"|"warm"|"cold"), priority ("high"|"medium"|"low"), nextAction (string), notes (string).\n\nSCORING WEIGHTS (Conservative):\n- Role is CEO/CTO/VP/Director: +25\n- Role is Manager/Team Lead: +10\n- Role is Intern/Junior/Trainee: -10\n- Company name is known: +15\n- Industry is known: +10\n- Company size > 100 employees: +15\n- Company size > 10: +10\n- Message > 50 characters: +10\n- Message < 10 characters: -5\n- Email is provided and valid: +10\n- Position/role is filled in: +10\n\nRULES:\n- Score > 70: hot tier, high priority\n- Score 40-70: warm tier, medium priority\n- Score < 40: cold tier, low priority\n- BE STRICT. Not every lead is hot.';

const leadData = {
  name: d.name,
  email: d.email,
  company: d.enrichedCompany || d.company,
  role: d.position || d.enrichedRole || '',
  industry: d.enrichedIndustry || '',
  companySize: d.enrichedSize || '',
  message: d.message || '',
  source: d.source
};

d._body = JSON.stringify({
  model: 'qwen3-32b',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: 'Score this lead:\n' + JSON.stringify(leadData, null, 2) }
  ],
  temperature: 0.1
});
return [d];

const resp = $input.first().json;
const input = $('Prep Scorer A').first().json;
const content = resp.choices?.[0]?.message?.content || resp.output || resp.text || '{}';
const clean = String(content).replace(/```json?/gi, '').replace(/```/g, '').trim();
let parsed = {};
try { parsed = JSON.parse(clean); } catch(e) {
  const m = clean.match(/\{[\s\S]*\}/);
  if (m) try { parsed = JSON.parse(m[0]); } catch(e2) {}
}
input.leadScore = parsed.leadScore || 0;
input.leadTier = parsed.leadTier || 'cold';
input.priority = parsed.priority || 'low';
input.nextAction = parsed.nextAction || 'Nurture';
input.scorerNotes = parsed.notes || '';
input.promptVersion = 'A';
input._usage = resp.usage || null;
input._model = resp.model || 'qwen3-32b';
delete input._body;
return [input];

