// Нормализация полей лида для записи в CRM (сама запись — нода 'Save Lead (Postgres)', параметры $1..$16).
const d = $input.first().json;
d.status = d.leadScore > 70 ? 'hot_emailed' : (d.leadScore > 0 ? 'nurture' : 'invalid');
return [{ json: {
  lead_id: d.leadId, name: d.name, email: d.email, phone: d.phone,
  company: d.enrichedCompany || d.company || '',
  company_industry: d.enrichedIndustry || '',
  company_size: d.enrichedSize || '',
  role: d.position || d.enrichedRole || (d.companyFound ? 'Executive' : ''),
  source: d.source, message: d.message,
  lead_score: d.leadScore, lead_tier: d.leadTier, priority: d.priority,
  prompt_version: d.promptVersion, status: d.status, next_action: d.nextAction
} }];

// Финальный ответ воркфлоу: лид + сводка A/B (нативная Postgres-нода) + стоимость скоринга.
const saved = $('Save Lead (Postgres)').first().json;
let costRow = null;
try { costRow = $('Log LLM Cost (Postgres)').first().json; } catch (e) {}
const rows = $input.all().map(i => i.json);
const ab = {};
for (const row of rows) ab[row.arm] = { n: row.n, avg: row.avg_score };
let winner = null;
if (ab.A && ab.B) winner = ab.A.avg >= ab.B.avg ? 'A' : 'B';

return [{
  summary: 'Lead processed',
  leadId: saved.lead_id,
  score: saved.lead_score,
  tier: saved.lead_tier,
  prompt: saved.prompt_version,
  status: saved.status,
  ab_stats: ab,
  ab_winner: winner,
  cost_usd: costRow ? costRow.cost_usd : null
}];
